SELECT COUNT(1)
FROM ai_business_application_object
WHERE tenant_id = #{tenantId}
  AND application_id = #{applicationId}
  AND del_flag = '0'

SELECT COUNT(1)
FROM ai_business_application_object
WHERE tenant_id = #{tenantId}
  AND object_id = #{objectId}
  AND del_flag = '0'

SELECT COUNT(1)
FROM ai_business_application_object ao
INNER JOIN ai_business_object o
  ON o.tenant_id = ao.tenant_id
 AND o.id = ao.object_id
 AND o.del_flag = '0'
WHERE ao.tenant_id = #{tenantId}
  AND ao.application_id = #{applicationId}
  AND ao.del_flag = '0'
  AND o.suite_code = #{suiteCode}
  AND o.object_code = #{objectCode}

mapper.update:
UPDATE ai_business_application_object
SET del_flag = '1',
    update_time = NOW()
WHERE tenant_id = #{tenantId}
  AND application_id = #{applicationId}
  AND del_flag = '0'
